-- Train Defect Reporter v2: D&V plus Exam Mode
create extension if not exists pgcrypto;
do $$ begin create type public.app_role as enum ('user','admin'); exception when duplicate_object then null; end $$;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,role public.app_role not null default 'user',created_at timestamptz not null default now());
create table if not exists public.defects(id uuid primary key default gen_random_uuid(),train_number text not null check(train_number~'^[0-9]{6}$'),coach_number text not null check(coach_number~'^[0-9]{3}$'),description text not null check(length(trim(description))>=5),image_path text not null,reported_by uuid not null constraint defects_reported_by_fkey references public.profiles(id) on delete restrict,created_at timestamptz not null default now());
create table if not exists public.fleets(id uuid primary key default gen_random_uuid(),code text not null unique,name text not null unique,coach_numbers text[] not null,active boolean not null default true,created_at timestamptz not null default now());
insert into public.fleets(code,name,coach_numbers) values('AZUMA','Azuma',array['829','828','827','826','825','824','823','822','821']) on conflict(code) do update set name=excluded.name,coach_numbers=excluded.coach_numbers;
create table if not exists public.exams(id uuid primary key default gen_random_uuid(),unit_number text not null check(unit_number~'^[0-9]{6}$'),fleet_id uuid not null references public.fleets(id),status text not null default 'open' check(status in('open','complete','deleted')),created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,purge_after timestamptz,deleted_by uuid references public.profiles(id));
create unique index if not exists one_live_exam_per_unit on public.exams(unit_number) where deleted_at is null;
create table if not exists public.exam_defects(id uuid primary key default gen_random_uuid(),exam_id uuid not null references public.exams(id) on delete cascade,coach_number text not null check(coach_number~'^[0-9]{3}$'),description text not null check(length(trim(description))>=3),reported_by uuid not null constraint exam_defects_reported_by_fkey references public.profiles(id),created_at timestamptz not null default now(),sap_booked boolean not null default false,sap_booked_at timestamptz,sap_booked_by uuid references public.profiles(id));
create index if not exists exam_defects_exam_coach_idx on public.exam_defects(exam_id,coach_number,created_at);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',split_part(new.email,'@',1))) on conflict(id) do nothing;return new;end$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and role='admin')$$;
create or replace function public.touch_exam() returns trigger language plpgsql security definer set search_path=public as $$begin update public.exams set updated_at=now() where id=coalesce(new.exam_id,old.exam_id);return coalesce(new,old);end$$;
drop trigger if exists touch_exam_on_defect on public.exam_defects;create trigger touch_exam_on_defect after insert or update or delete on public.exam_defects for each row execute procedure public.touch_exam();
create or replace function public.set_sap_audit() returns trigger language plpgsql set search_path=public as $$begin if new.sap_booked is distinct from old.sap_booked then new.sap_booked_at=case when new.sap_booked then now() else null end;new.sap_booked_by=case when new.sap_booked then auth.uid() else null end;end if;return new;end$$;
drop trigger if exists audit_sap_booking on public.exam_defects;create trigger audit_sap_booking before update on public.exam_defects for each row execute procedure public.set_sap_audit();
create or replace function public.soft_delete_exam(target_exam uuid) returns void language plpgsql security definer set search_path=public as $$begin if not public.is_admin() then raise exception 'Administrator access required';end if;update public.exams set status='deleted',deleted_at=now(),purge_after=now()+interval '10 days',deleted_by=auth.uid() where id=target_exam and deleted_at is null;if not found then raise exception 'Exam not found or already deleted';end if;end$$;
create or replace function public.purge_expired_exams() returns integer language plpgsql security definer set search_path=public as $$declare n integer;begin if auth.uid() is not null and not public.is_admin() then raise exception 'Administrator access required';end if;delete from public.exams where deleted_at is not null and purge_after<=now();get diagnostics n=row_count;return n;end$$;
alter table public.profiles enable row level security;alter table public.defects enable row level security;alter table public.fleets enable row level security;alter table public.exams enable row level security;alter table public.exam_defects enable row level security;
drop policy if exists "read own profile" on public.profiles;create policy "read own profile" on public.profiles for select to authenticated using(id=auth.uid() or public.is_admin());
drop policy if exists "users create defects" on public.defects;create policy "users create defects" on public.defects for insert to authenticated with check(reported_by=auth.uid());
drop policy if exists "admins read defects" on public.defects;create policy "admins read defects" on public.defects for select to authenticated using(public.is_admin());
drop policy if exists "admins delete defects" on public.defects;create policy "admins delete defects" on public.defects for delete to authenticated using(public.is_admin());
create policy "authenticated read fleets" on public.fleets for select to authenticated using(true);
create policy "users read live exams admins all" on public.exams for select to authenticated using(deleted_at is null or public.is_admin());
create policy "users create exams" on public.exams for insert to authenticated with check(created_by=auth.uid() and deleted_at is null);
create policy "users read exam defects" on public.exam_defects for select to authenticated using(exists(select 1 from public.exams e where e.id=exam_id and(e.deleted_at is null or public.is_admin())));
create policy "users add exam defects" on public.exam_defects for insert to authenticated with check(reported_by=auth.uid() and exists(select 1 from public.exams e where e.id=exam_id and e.deleted_at is null));
create policy "admins update exam defects" on public.exam_defects for update to authenticated using(public.is_admin()) with check(public.is_admin());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('defect-images','defect-images',false,10485760,array['image/jpeg','image/png','image/webp','image/heic','image/heif']) on conflict(id) do update set public=false;
create policy "users upload own defect images" on storage.objects for insert to authenticated with check(bucket_id='defect-images' and(storage.foldername(name))[1]=auth.uid()::text);
create policy "admins read defect images" on storage.objects for select to authenticated using(bucket_id='defect-images' and public.is_admin());
create policy "admins delete defect images" on storage.objects for delete to authenticated using(bucket_id='defect-images' and public.is_admin());
create policy "users delete own orphaned images" on storage.objects for delete to authenticated using(bucket_id='defect-images' and(storage.foldername(name))[1]=auth.uid()::text);
-- Schedule daily purging in Supabase Dashboard > Integrations > Cron, or run: select public.purge_expired_exams();
-- Promote admin: update public.profiles set role='admin' where id=(select id from auth.users where email='admin@example.com');
